CREATE TABLE IF NOT EXISTS workforce_submissions(id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id),employee_id UUID REFERENCES workforce_employees(id),applicant_id UUID REFERENCES applicant_accounts(id),application_id UUID REFERENCES ats_applications(id),title TEXT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,content BYTEA NOT NULL CHECK(octet_length(content)<=2097152),consented_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),feedback TEXT NOT NULL DEFAULT '',reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK((employee_id IS NOT NULL AND applicant_id IS NULL) OR (employee_id IS NULL AND applicant_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS workforce_submissions_tenant ON workforce_submissions(employer_id,created_at);
CREATE TABLE IF NOT EXISTS employee_confirmation_decisions(id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id),employee_id UUID NOT NULL REFERENCES workforce_employees(id),decision TEXT NOT NULL CHECK(decision IN ('confirmed','extended','not_confirmed')),effective_date DATE NOT NULL,review_date DATE,notes TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
